<template>
  <a-card :bordered="false">
    <div class="card-title">{{ $route.meta.title }}</div>
    <div class="table-operator">
      <a-row>
        <a-col :span="6">
          <a-button type="primary" icon="plus" @click="handleAdd">新增配置</a-button>
        </a-col>
      </a-row>
    </div>
    <s-table
      ref="table"
      rowKey="id"
      :loading="isLoading"
      :columns="columns"
      :data="loadData"
      :pageSize="15"
    >
      <span slot="discount_range" slot-scope="text, item">
        {{ item.discount_min }}~{{ item.discount_max }}
      </span>
      <span slot="is_active" slot-scope="text">
        <a-tag :color="text ? 'green' : 'red'">{{ text ? '启用' : '停用' }}</a-tag>
      </span>
      <span slot="action" slot-scope="text, item">
        <a style="margin-right: 8px;" @click="handleEdit(item)">编辑</a>
        <a style="margin-right: 8px;" @click="handleRefresh(item)">刷新</a>
      </span>
    </s-table>
    <AddForm ref="AddForm" @handleSubmit="handleRefreshTable" />
    <EditForm ref="EditForm" @handleSubmit="handleRefreshTable" />
  </a-card>
</template>

<script>
import * as Api from '@/api/membership/randomDiscounts'
import { STable } from '@/components'
import AddForm from './modules/AddForm'
import EditForm from './modules/EditForm'

export default {
  name: 'MembershipRandomDiscount',
  components: {
    STable,
    AddForm,
    EditForm
  },
  data () {
    return {
      isLoading: false,
      columns: [
        { title: 'ID', dataIndex: 'id' },
        { title: '会员卡ID', dataIndex: 'card_id' },
        { title: '刷新周期(天)', dataIndex: 'period_days' },
        { title: '随机比例', dataIndex: 'product_ratio' },
        { title: '折扣范围', dataIndex: 'discount_min', scopedSlots: { customRender: 'discount_range' } },
        { title: '状态', dataIndex: 'is_active', scopedSlots: { customRender: 'is_active' } },
        { title: '下次刷新', dataIndex: 'next_refresh_at' },
        { title: '操作', dataIndex: 'action', scopedSlots: { customRender: 'action' } }
      ],
      loadData: param => {
        return Api.list({ ...param, per_page: 15 })
          .then(response => response)
      }
    }
  },
  methods: {
    handleAdd () {
      this.$refs.AddForm.add()
    },
    handleEdit (item) {
      this.$refs.EditForm.edit(item)
    },
    handleRefresh (item) {
      Api.refresh(item.id).then((result) => {
        this.$message.success(result.message || '刷新成功', 1.5)
        this.handleRefreshTable()
      })
    },
    handleRefreshTable (bool = false) {
      this.$refs.table.refresh(bool)
    }
  }
}
</script>
