<template>
  <a-card :bordered="false">
    <div class="card-title">{{ $route.meta.title }}</div>
    <div class="table-operator">
      <a-row>
        <a-col :span="6">
          <a-button type="primary" icon="plus" @click="handleAdd">新增会员卡</a-button>
        </a-col>
      </a-row>
    </div>
    <s-table
      ref="table"
      rowKey="id"
      :loading="isLoading"
      :columns="columns"
      :data="loadData"
      :pageSize="15"
    >
      <span slot="type" slot-scope="text">
        {{ typeLabel(text) }}
      </span>
      <span slot="is_active" slot-scope="text">
        <a-tag :color="text ? 'green' : 'red'">{{ text ? '启用' : '停用' }}</a-tag>
      </span>
      <span slot="action" slot-scope="text, item">
        <a style="margin-right: 8px;" @click="handleEdit(item)">编辑</a>
        <a @click="handleDelete(item)">删除</a>
      </span>
    </s-table>
    <AddForm ref="AddForm" @handleSubmit="handleRefresh" />
    <EditForm ref="EditForm" @handleSubmit="handleRefresh" />
  </a-card>
</template>

<script>
import * as Api from '@/api/membership/cards'
import { STable } from '@/components'
import AddForm from './modules/AddForm'
import EditForm from './modules/EditForm'

export default {
  name: 'MembershipCards',
  components: {
    STable,
    AddForm,
    EditForm
  },
  data () {
    return {
      isLoading: false,
      columns: [
        { title: 'ID', dataIndex: 'id' },
        { title: '会员卡名称', dataIndex: 'name' },
        { title: '等级', dataIndex: 'level' },
        { title: '开通方式', dataIndex: 'type', scopedSlots: { customRender: 'type' } },
        { title: '排序', dataIndex: 'sort' },
        { title: '状态', dataIndex: 'is_active', scopedSlots: { customRender: 'is_active' } },
        { title: '更新时间', dataIndex: 'updated_at' },
        { title: '操作', dataIndex: 'action', scopedSlots: { customRender: 'action' } }
      ],
      loadData: param => {
        return Api.list({ ...param, per_page: 15 })
          .then(response => response)
      }
    }
  },
  methods: {
    typeLabel (type) {
      if (type === 'subscription') return '订阅制'
      if (type === 'recharge') return '充值制'
      if (type === 'one_time') return '一次性'
      return type
    },
    handleAdd () {
      this.$refs.AddForm.add()
    },
    handleEdit (item) {
      this.$refs.EditForm.edit(item)
    },
    handleDelete (item) {
      const app = this
      const modal = this.$confirm({
        title: '确认删除该会员卡？',
        content: '删除后将不可恢复',
        onOk () {
          return Api.deleted(item.id)
            .then((result) => {
              app.$message.success(result.message || '删除成功', 1.5)
              app.handleRefresh()
            })
            .finally(() => modal.destroy())
        }
      })
    },
    handleRefresh (bool = false) {
      this.$refs.table.refresh(bool)
    }
  }
}
</script>
