import { axios } from '@/utils/request'

const api = {
  list: '/membership/random_discounts',
  detail: '/membership/random_discounts/{id}',
  add: '/membership/random_discounts',
  edit: '/membership/random_discounts/{id}',
  refresh: '/membership/random_discounts/{id}/refresh',
  items: '/membership/random_discounts/{id}/items'
}

export function list (params) {
  return axios({
    url: api.list,
    method: 'get',
    params
  })
}

export function detail (id, params) {
  return axios({
    url: api.detail.replace('{id}', id),
    method: 'get',
    params
  })
}

export function add (data) {
  return axios({
    url: api.add,
    method: 'post',
    data
  })
}

export function edit (id, data) {
  return axios({
    url: api.edit.replace('{id}', id),
    method: 'patch',
    data
  })
}

export function refresh (id) {
  return axios({
    url: api.refresh.replace('{id}', id),
    method: 'post'
  })
}

export function items (id, params) {
  return axios({
    url: api.items.replace('{id}', id),
    method: 'get',
    params
  })
}
