<script>
import * as CategoryApi from '@/api/category'

export default {
  name: 'BenefitConfigForm',
  props: {
    record: {
      type: Object,
      required: true
    },
    benefitTypes: {
      type: Object,
      default: () => ({})
    }
  },
  data () {
    return {
      categoryList: [],
      categoriesLoaded: false
    }
  },
  methods: {
    loadCategories () {
      if (this.categoriesLoaded) return
      CategoryApi.list({ all: true }).then(res => {
        this.categoryList = this.formatTreeData(res.data || res)
        this.categoriesLoaded = true
      })
    },
    formatTreeData (list, parentId = 0) {
      const result = []
      for (const item of list) {
        if (item.parent_id === parentId) {
          const children = this.formatTreeData(list, item.id)
          const node = {
            title: item.name,
            value: item.id,
            key: item.id
          }
          if (children.length > 0) {
            node.children = children
          }
          result.push(node)
        }
      }
      return result
    }
  }
}
</script>

