import { axios } from '@/utils/request'

const api = {
  list: '/membership/cards',
  detail: '/membership/cards/{id}',
  add: '/membership/cards',
  edit: '/membership/cards/{id}',
  delete: '/membership/cards/{id}'
}

export function list (params) {
  return axios({
    url: api.list,
    method: 'get',
    params
  })
}

export function detail (id, params) {
  return axios({
    url: api.detail.replace('{id}', id),
    method: 'get',
    params
  })
}

export function add (data) {
  return axios({
    url: api.add,
    method: 'post',
    data
  })
}

export function edit (id, data) {
  return axios({
    url: api.edit.replace('{id}', id),
    method: 'patch',
    data
  })
}

export function deleted (id) {
  return axios({
    url: api.delete.replace('{id}', id),
    method: 'delete'
  })
}
