<template>
  <a-modal
    :title="title"
    :width="960"
    :visible="visible"
    :confirmLoading="confirmLoading"
    :maskClosable="false"
    @ok="handleSubmit"
    @cancel="handleCancel"
  >
    <a-spin :spinning="confirmLoading">
      <a-form :form="form">
        <a-divider>基本信息</a-divider>
        <a-row :gutter="16">
          <a-col :span="12">
            <a-form-item label="会员卡名称" :labelCol="labelCol" :wrapperCol="wrapperCol">
              <a-input
                placeholder="如：黄金会员"
                v-decorator="['name', { rules: [{ required: true, message: '请输入会员卡名称' }] }]"
              />
            </a-form-item>
          </a-col>
          <a-col :span="12">
            <a-form-item label="会员等级" :labelCol="labelCol" :wrapperCol="wrapperCol" extra="数字越大等级越高">
              <a-input-number :min="1" style="width: 100%" v-decorator="['level', { rules: [{ required: true, message: '请输入会员等级' }] }]" />
            </a-form-item>
          </a-col>
        </a-row>
        <a-row :gutter="16">
          <a-col :span="12">
            <a-form-item label="主题色" :labelCol="labelCol" :wrapperCol="wrapperCol">
              <div class="color-picker-wrapper">
                <a-input
                  v-decorator="['color']"
                  style="width: calc(100% - 50px)"
                  placeholder="#FFD700"
                />
                <span
                  class="color-preview"
                  :style="{ backgroundColor: form.getFieldValue('color') || '#FFD700' }"
                  @click="randomColor"
                  title="点击随机生成"
                ></span>
              </div>
            </a-form-item>
          </a-col>
          <a-col :span="12">
            <a-form-item label="排序" :labelCol="labelCol" :wrapperCol="wrapperCol" extra="数字越小越靠前">
              <a-input-number :min="0" style="width: 100%" v-decorator="['sort']" />
            </a-form-item>
          </a-col>
        </a-row>

        <a-divider>开通方式与定价</a-divider>
        <a-form-item label="开通方式" :labelCol="{span: 3}" :wrapperCol="{span: 21}">
          <a-radio-group v-decorator="['type', { rules: [{ required: true }] }]" @change="onTypeChange">
            <a-radio value="subscription">订阅制（按月/季/年付费）</a-radio>
            <a-radio value="recharge">充值制（充值固定金额，余额消费完失效）</a-radio>
            <a-radio value="one_time">一次性（付费后永久有效）</a-radio>
          </a-radio-group>
        </a-form-item>

        <!-- 订阅制定价 -->
        <div v-if="cardType === 'subscription'" class="pricing-section">
          <a-row :gutter="16">
            <a-col :span="8">
              <a-form-item label="月付价格" :labelCol="{span: 8}" :wrapperCol="{span: 16}">
                <a-input-number :min="0" :precision="2" style="width: 100%" v-decorator="['pricing_monthly']" placeholder="9.9" />
              </a-form-item>
            </a-col>
            <a-col :span="8">
              <a-form-item label="季付价格" :labelCol="{span: 8}" :wrapperCol="{span: 16}">
                <a-input-number :min="0" :precision="2" style="width: 100%" v-decorator="['pricing_quarterly']" placeholder="26.9" />
              </a-form-item>
            </a-col>
            <a-col :span="8">
              <a-form-item label="年付价格" :labelCol="{span: 8}" :wrapperCol="{span: 16}">
                <a-input-number :min="0" :precision="2" style="width: 100%" v-decorator="['pricing_yearly']" placeholder="99" />
              </a-form-item>
            </a-col>
          </a-row>
        </div>

        <!-- 充值制定价 -->
        <div v-if="cardType === 'recharge'" class="pricing-section">
          <a-row :gutter="16">
            <a-col :span="8">
              <a-form-item label="充值金额" :labelCol="{span: 8}" :wrapperCol="{span: 16}">
                <a-input-number :min="0" :precision="2" style="width: 100%" v-decorator="['pricing_amount', { rules: [{ required: true, message: '请输入充值金额' }] }]" placeholder="999" />
              </a-form-item>
            </a-col>
            <a-col :span="8">
              <a-form-item label="赠送比例" :labelCol="{span: 8}" :wrapperCol="{span: 16}" extra="如10%表示充1000送100">
                <a-input-number :min="0" :max="100" :precision="0" style="width: 100%" v-decorator="['pricing_bonus_ratio']" />
                <span style="margin-left: 8px">%</span>
              </a-form-item>
            </a-col>
            <a-col :span="8">
              <a-form-item label="有效期" :labelCol="{span: 8}" :wrapperCol="{span: 16}" extra="天数，0表示余额用完失效">
                <a-input-number :min="0" :precision="0" style="width: 100%" v-decorator="['duration_days']" placeholder="365" />
              </a-form-item>
            </a-col>
          </a-row>
          <a-form-item :labelCol="{span: 3}" :wrapperCol="{span: 21}">
            <a-checkbox v-decorator="['pricing_is_locked', { valuePropName: 'checked' }]">
              锁定余额（不可提现，仅可购物消费）
            </a-checkbox>
          </a-form-item>
        </div>

        <!-- 一次性定价 -->
        <div v-if="cardType === 'one_time'" class="pricing-section">
          <a-row :gutter="16">
            <a-col :span="8">
              <a-form-item label="购买价格" :labelCol="{span: 8}" :wrapperCol="{span: 16}">
                <a-input-number :min="0" :precision="2" style="width: 100%" v-decorator="['pricing_price', { rules: [{ required: true, message: '请输入购买价格' }] }]" placeholder="299" />
              </a-form-item>
            </a-col>
          </a-row>
        </div>

        <a-form-item label="状态" :labelCol="{span: 3}" :wrapperCol="{span: 21}">
          <a-switch v-decorator="['is_active', { valuePropName: 'checked' }]" checkedChildren="启用" unCheckedChildren="停用" />
        </a-form-item>

        <a-divider>会员权益配置</a-divider>
        <div class="benefits-section">
          <div class="benefits-toolbar">
            <a-button type="dashed" icon="plus" @click="addBenefit">添加权益</a-button>
          </div>
          <a-table
            v-if="benefits.length"
            :columns="benefitColumns"
            :dataSource="benefits"
            :pagination="false"
            rowKey="key"
            size="small"
          >
            <template slot="benefit_type" slot-scope="text, record">
              <a-select
                v-model="record.benefit_type"
                style="width: 160px"
                placeholder="选择权益类型"
                @change="val => onBenefitTypeChange(record, val)"
              >
                <a-select-opt-group v-for="(group, groupKey) in benefitTypes" :key="groupKey" :label="groupLabels[groupKey]">
                  <a-select-option v-for="(item, key) in group" :key="key" :value="key">{{ item.name }}</a-select-option>
                </a-select-opt-group>
              </a-select>
            </template>
            <template slot="config" slot-scope="text, record">
              <BenefitConfigForm :record="record" :benefitTypes="benefitTypes" />
            </template>
            <template slot="is_active" slot-scope="text, record">
              <a-switch v-model="record.is_active" size="small" />
            </template>
            <template slot="action" slot-scope="text, record, index">
              <a @click="removeBenefit(index)" style="color: #f5222d">删除</a>
            </template>
          </a-table>
          <a-empty v-else description="暂无权益配置，点击上方按钮添加" />
        </div>
      </a-form>
    </a-spin>
  </a-modal>
</template>

<script>
import * as Api from '@/api/membership/cards'
import BenefitConfigForm from './BenefitConfigForm'

// 生成随机颜色
const generateRandomColor = () => {
  const colors = ['#FFD700', '#FF6B6B', '#4ECDC4', '#45B7D1', '#96CEB4', '#FFEAA7', '#DDA0DD', '#98D8C8', '#F7DC6F', '#BB8FCE']
  return colors[Math.floor(Math.random() * colors.length)]
}

export default {
  components: { BenefitConfigForm },
  data () {
    return {
      title: '编辑会员卡',
      labelCol: { span: 6 },
      wrapperCol: { span: 18 },
      visible: false,
      confirmLoading: false,
      form: this.$form.createForm(this),
      recordId: null,
      cardType: 'subscription',
      benefits: [],
      benefitKey: 0,
      benefitTypes: {
        shipping: {
          free_shipping: { name: '免运费', params: ['enabled'] },
          shipping_discount: { name: '运费折扣', params: ['discount'] },
          monthly_free_shipping: { name: '每月免运费次数', params: ['times'] },
          monthly_shipping_voucher: { name: '每月运费券', params: ['count', 'amount'] }
        },
        discount: {
          global_discount: { name: '全商品折扣', params: ['discount'] },
          category_discount: { name: '分类折扣', params: ['category_ids', 'discount'] },
          product_discount: { name: '商品折扣', params: ['product_ids', 'discount'] },
          member_price: { name: '会员专享价', params: ['enabled'] }
        },
        voucher: {
          monthly_voucher: { name: '每月赠券', params: ['voucher_type', 'count', 'config'] }
        },
        product_access: {
          exclusive_product: { name: '专属商品购买权', params: ['enabled'] },
          purchase_limit_boost: { name: '限购提升', params: ['multiplier'] }
        }
      },
      groupLabels: {
        shipping: '运费相关',
        discount: '价格折扣',
        voucher: '优惠券',
        product_access: '商品权限'
      },
      benefitColumns: [
        { title: '权益类型', dataIndex: 'benefit_type', scopedSlots: { customRender: 'benefit_type' }, width: 180 },
        { title: '配置参数', dataIndex: 'config', scopedSlots: { customRender: 'config' } },
        { title: '启用', dataIndex: 'is_active', scopedSlots: { customRender: 'is_active' }, width: 80 },
        { title: '操作', dataIndex: 'action', scopedSlots: { customRender: 'action' }, width: 80 }
      ]
    }
  },
  methods: {
    edit (record) {
      this.recordId = record.id
      this.visible = true
      this.cardType = record.type
      this.benefitKey = 0

      // 解析 benefits
      this.benefits = (record.benefits || []).map(b => ({
        key: ++this.benefitKey,
        id: b.id,
        benefit_type: b.benefit_type,
        config: b.config || {},
        sort: b.sort || 100,
        is_active: b.is_active !== false
      }))

      this.$nextTick(() => {
        const fieldsValue = {
          name: record.name,
          level: record.level,
          type: record.type,
          color: record.color || '#FFD700',
          is_active: record.is_active,
          sort: record.sort
        }

        // 解析 pricing
        const pricing = record.pricing || {}
        if (record.type === 'subscription') {
          fieldsValue.pricing_monthly = pricing.monthly?.price
          fieldsValue.pricing_quarterly = pricing.quarterly?.price
          fieldsValue.pricing_yearly = pricing.yearly?.price
        } else if (record.type === 'recharge') {
          fieldsValue.pricing_amount = pricing.amount
          fieldsValue.pricing_bonus_ratio = (pricing.bonus_ratio || 0) * 100
          fieldsValue.pricing_is_locked = pricing.is_locked !== false
          fieldsValue.duration_days = record.duration_days || 0
        } else if (record.type === 'one_time') {
          fieldsValue.pricing_price = pricing.price
        }

        this.form.setFieldsValue(fieldsValue)
      })
    },
    randomColor () {
      const color = generateRandomColor()
      this.form.setFieldsValue({ color })
    },
    onTypeChange (e) {
      this.cardType = e.target.value
    },
    addBenefit () {
      this.benefits.push({
        key: ++this.benefitKey,
        benefit_type: '',
        config: {},
        sort: 100,
        is_active: true
      })
    },
    removeBenefit (index) {
      this.benefits.splice(index, 1)
    },
    onBenefitTypeChange (record, type) {
      // 根据类型初始化默认配置
      const defaults = {
        free_shipping: { enabled: true },
        shipping_discount: { discount: 0.8 },
        monthly_free_shipping: { times: 5 },
        monthly_shipping_voucher: { count: 3, amount: 5 },
        global_discount: { discount: 0.95 },
        category_discount: { category_ids: [], discount: 0.9 },
        product_discount: { product_ids: [], discount: 0.85 },
        member_price: { enabled: true },
        monthly_voucher: { voucher_type: 'discount', count: 2, amount_limit: 30, save_amount: 5 },
        exclusive_product: { enabled: true },
        purchase_limit_boost: { multiplier: 2 }
      }
      record.config = defaults[type] || {}
    },
    handleSubmit (e) {
      e.preventDefault()
      const { form: { validateFields } } = this
      validateFields((errors, values) => {
        if (!errors) {
          const payload = this.normalizePayload(values)
          if (!payload) return
          this.onFormSubmit(payload)
        }
      })
    },
    handleCancel () {
      this.visible = false
      this.recordId = null
      this.form.resetFields()
      this.benefits = []
      this.cardType = 'subscription'
    },
    normalizePayload (values) {
      const payload = {
        name: values.name,
        level: values.level,
        type: values.type,
        color: values.color,
        is_active: values.is_active,
        sort: values.sort
      }

      // 构建 pricing
      if (values.type === 'subscription') {
        payload.pricing = {}
        if (values.pricing_monthly) payload.pricing.monthly = { price: values.pricing_monthly }
        if (values.pricing_quarterly) payload.pricing.quarterly = { price: values.pricing_quarterly }
        if (values.pricing_yearly) payload.pricing.yearly = { price: values.pricing_yearly }
        if (Object.keys(payload.pricing).length === 0) {
          this.$message.error('订阅制至少需要设置一个价格')
          return null
        }
      } else if (values.type === 'recharge') {
        payload.pricing = {
          amount: values.pricing_amount,
          bonus_ratio: (values.pricing_bonus_ratio || 0) / 100,
          is_locked: values.pricing_is_locked
        }
        payload.duration_days = values.duration_days || null
        payload.duration_type = values.duration_days > 0 ? 'days' : 'balance'
      } else if (values.type === 'one_time') {
        payload.pricing = { price: values.pricing_price }
        payload.duration_type = 'forever'
      }

      // 构建 benefits
      payload.benefits = this.benefits
        .filter(b => b.benefit_type)
        .map(b => ({
          id: b.id,
          benefit_type: b.benefit_type,
          config: b.config,
          sort: b.sort || 100,
          is_active: b.is_active
        }))

      return payload
    },
    onFormSubmit (values) {
      this.confirmLoading = true
      Api.edit(this.recordId, values)
        .then((result) => {
          this.$message.success(result.message || '保存成功', 1.5)
          this.handleCancel()
          this.$emit('handleSubmit', values)
        })
        .finally(() => {
          this.confirmLoading = false
        })
    }
  }
}
</script>

<style lang="less" scoped>
