  border-radius: 4px;
  border: 1px solid #d9d9d9;
  cursor: pointer;
  flex-shrink: 0;
  &:hover {
    border-color: #40a9ff;
  }
}
.pricing-section {
  background: #fafafa;
  padding: 16px;
  border-radius: 4px;
  margin-bottom: 16px;
}
.benefits-section {
  .benefits-toolbar {
    margin-bottom: 16px;
  }
}
</style>
