<template>
  <a-modal
    :title="title"
    :width="720"
    :visible="visible"
    :confirmLoading="confirmLoading"
    :maskClosable="false"
    @ok="handleSubmit"
    @cancel="handleCancel"
  >
    <a-spin :spinning="confirmLoading">
      <a-form :form="form">
        <a-form-item label="会员卡ID" :labelCol="labelCol" :wrapperCol="wrapperCol" extra="为空表示通用活动">
          <a-input-number :min="1" v-decorator="['card_id']" />
        </a-form-item>
        <a-form-item label="刷新周期(天)" :labelCol="labelCol" :wrapperCol="wrapperCol">
          <a-input-number :min="1" v-decorator="['period_days', { initialValue: 7 }]" />
        </a-form-item>
        <a-form-item label="刷新时间" :labelCol="labelCol" :wrapperCol="wrapperCol" extra="格式 HH:mm:ss">
          <a-input v-decorator="['refresh_time', { initialValue: '00:00:00' }]" />
        </a-form-item>
        <a-form-item label="商品来源" :labelCol="labelCol" :wrapperCol="wrapperCol">
          <a-select v-decorator="['source_type', { initialValue: 'all' }]">
            <a-select-option value="all">全部商品</a-select-option>
            <a-select-option value="category">指定分类</a-select-option>
            <a-select-option value="tag">指定标签</a-select-option>
          </a-select>
        </a-form-item>
        <a-form-item label="来源ID" :labelCol="labelCol" :wrapperCol="wrapperCol" extra="JSON 数组，如 [1,2,3]">
          <a-textarea v-decorator="['source_ids']" :autoSize="{ minRows: 2 }" />
        </a-form-item>
        <a-form-item label="排除商品" :labelCol="labelCol" :wrapperCol="wrapperCol" extra="JSON 数组，如 [100,200]">
          <a-textarea v-decorator="['exclude_product_ids']" :autoSize="{ minRows: 2 }" />
        </a-form-item>
        <a-form-item label="随机比例" :labelCol="labelCol" :wrapperCol="wrapperCol" extra="0~1">
          <a-input-number :min="0" :max="1" :step="0.01" v-decorator="['product_ratio', { initialValue: 0.3 }]" />
        </a-form-item>
        <a-form-item label="折扣范围" :labelCol="labelCol" :wrapperCol="wrapperCol">
          <a-input-number :min="0" :max="1" :step="0.01" v-decorator="['discount_min', { initialValue: 0.7 }]" />
          <span class="ml-10">~</span>
          <a-input-number :min="0" :max="1" :step="0.01" v-decorator="['discount_max', { initialValue: 0.9 }]" />
        </a-form-item>
        <a-form-item label="原价门槛" :labelCol="labelCol" :wrapperCol="wrapperCol">
          <a-input-number :min="0" v-decorator="['min_price', { initialValue: 0 }]" />
        </a-form-item>
        <a-form-item label="启用状态" :labelCol="labelCol" :wrapperCol="wrapperCol">
          <a-switch v-decorator="['is_active', { valuePropName: 'checked', initialValue: true }]" />
        </a-form-item>
      </a-form>
    </a-spin>
  </a-modal>
</template>

<script>
import * as Api from '@/api/membership/randomDiscounts'

export default {
  data () {
    return {
      title: '新增随机折扣配置',
      labelCol: { span: 6 },
      wrapperCol: { span: 16 },
      visible: false,
      confirmLoading: false,
      form: this.$form.createForm(this)
    }
  },
  methods: {
    add () {
      this.visible = true
    },
    handleSubmit (e) {
      e.preventDefault()
      const { form: { validateFields } } = this
      validateFields((errors, values) => {
        if (!errors) {
          const payload = this.normalizePayload(values)
          if (!payload) return
          this.onFormSubmit(payload)
        }
      })
    },
    handleCancel () {
      this.visible = false
      this.form.resetFields()
    },
    normalizePayload (values) {
      const payload = { ...values }
      payload.source_ids = this.parseJson(payload.source_ids, '来源ID')
      if (payload.source_ids === false) return null
      payload.exclude_product_ids = this.parseJson(payload.exclude_product_ids, '排除商品')
      if (payload.exclude_product_ids === false) return null
      return payload
    },
    parseJson (value, label) {
      if (!value) return null
      try {
        const parsed = JSON.parse(value)
        if (!Array.isArray(parsed)) {
          this.$message.error(`${label}必须是JSON数组`)
          return false
        }
        return parsed
      } catch (e) {
        this.$message.error(`${label}不是有效的JSON`)
        return false
      }
    },
    onFormSubmit (values) {
      this.confirmLoading = true
      Api.add(values)
        .then((result) => {
          this.$message.success(result.message || '保存成功', 1.5)
          this.handleCancel()
          this.$emit('handleSubmit', values)
        })
        .finally(() => {
          this.confirmLoading = false
        })
    }
  }
}
</script>
